122	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
123	    @Override
124	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
125	        Owner owner = this.clinicService.findOwnerById(ownerId);
126	        if (owner == null) {
127	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
128	        }
129	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
130	    }
131	
132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Override
134	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
135	        HttpHeaders headers = new HttpHeaders();
136	        String idempotencyKey = this.request.getHeader(IDEMPOTENCY_KEY_HEADER);
137	        Integer existingId = this.idempotencyKeyRegistry.findOwnerId(idempotencyKey);
138	        if (existingId != null) {
139	            Owner existing = this.clinicService.findOwnerById(existingId);
140	            if (existing != null) {
141	                return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
142	            }
143	        }
144	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
145	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
146	        owner.setTelephone(normalizedTelephone);
147	        owner.setEmail(normalizeEmail(owner.getEmail()));
148	        applyAddress(owner);
149	        validatePostcode(owner.getCity(), owner.getPostcode());
150	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
151	        if (effectiveRegistrationDate == null) {
152	            effectiveRegistrationDate = LocalDate.now();
153	        } else if (effectiveRegistrationDate.isAfter(LocalDate.now())) {
154	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
155	                "registrationDate must not be later than the current server date");
156	        }
157	        effectiveRegistrationDate = rollToBusinessDay(effectiveRegistrationDate);
158	        owner.setRegistrationDate(effectiveRegistrationDate);
159	        if (countOwnersRegisteredOn(effectiveRegistrationDate) >= DAILY_CREATE_LIMIT) {
160	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
161	                "the maximum number of owners that may be created today has been reached");
162	        }
163	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
164	        // The household id is deterministic (derived from the last name and postcode), so every
165	        // owner is keyed to its household automatically, regardless of creation order.
166	        this.clinicService.assignHousehold(owner);
167	        // An owner joining an existing household is now admitted rather than rejected; their
168	        // membership level is instead capped relative to the household (see the level-ceiling rule
169	        // applied via the membershipLevelCap below).
170	        boolean householdInUse = this.clinicService.isHouseholdInUse(owner.getHouseholdId(), null);
171	        if (isIdentityKeyInUse(ownerMapper.toIdentityKey(owner), null)) {
172	            throw new ResponseStatusException(HttpStatus.CONFLICT,
173	                "an owner with the same identity already exists");
174	        }
175	        int ownersInCity = countOwnersInCity(owner.getCity());
176	        if (ownersInCity >= CITY_CAPACITY) {
177	            throw new ResponseStatusException(HttpStatus.CONFLICT,
178	                "city has reached its maximum number of owners");
179	        }
180	        owner.setCapacityWarning(ownersInCity >= CITY_CAPACITY_WARNING_THRESHOLD);
181	        owner.setMemberId(memberIdFor(owner));
182	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
183	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
184	        owner.setMembershipLevelCap(householdMembershipLevelCap(owner.getHouseholdId()));
185	        owner.setBulkSignupWarning(
186	            countOwnersRegisteredOn(effectiveRegistrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
187	        // A declared household member (one created with 'sharesHousehold' that joins an existing
188	        // household) is not a suspected duplicate, so it is never flagged as a possible duplicate.
189	        boolean declaredHouseholdMember = sharesHousehold && householdInUse;
190	        Owner softDuplicate = declaredHouseholdMember ? null : findPossibleDuplicate(owner);
191	        owner.setPossibleDuplicate(softDuplicate != null);
192	        owner.setPossibleDuplicateOf(softDuplicate == null ? null : softDuplicate.getId());
193	        this.clinicService.saveOwner(owner);
194	        this.idempotencyKeyRegistry.record(idempotencyKey, owner.getId());
195	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
196	        AUDIT.info("owner created: id={} memberId={} registrationDate={} membershipLevel={}",
197	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
198	            ownerDto.getMembershipLevel());
199	        OwnerCreatedEvent event = OwnerCreatedEvent.of(AUDIT_EVENT_SEQUENCE.incrementAndGet(),
200	            owner.getId(), primaryIdentifier(owner), ownerDto.getMembershipLevel());
201	        AUDIT.info(event.toJson());
202	        headers.setLocation(UriComponentsBuilder.newInstance()
203	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
204	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
205	    }
