274	
275	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
276	    @Override
277	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
278	        HttpHeaders headers = new HttpHeaders();
279	        Visit visit = visitMapper.toVisit(visitFieldsDto);
280	        Pet pet = new Pet();
281	        pet.setId(petId);
282	        visit.setPet(pet);
283	        this.clinicService.saveVisit(visit);
284	        VisitDto visitDto = visitMapper.toVisitDto(visit);
285	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
286	            .buildAndExpand(visit.getId()).toUri());
287	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
288	    }
289	
290	
291	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
292	    @Override
293	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
294	        Owner owner = this.clinicService.findOwnerById(ownerId);
295	        if (owner != null) {
296	            Pet pet = owner.getPet(petId);
297	            if (pet != null) {
298	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
299	            }
300	        }
301	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
302	    }
303	
304	    /**
305	     * The owner's current primary identifier, carried by the structured {@link OwnerCreatedEvent}.
306	     * An owner's primary identifier is its {@code memberId}; this single accessor is the one place that
307	     * decides which field is primary, so the audit event always carries the member id.
308	     *
309	     * @param owner the created owner
310	     * @return the owner's current primary identifier
311	     */
312	    private String primaryIdentifier(Owner owner) {
313	        return owner.getMemberId();
314	    }
315	
316	    /**
317	     * Builds the member id for a new owner, formatted {@code '<REGION><FY><HASH8><CHK>'} where REGION is
318	     * the region derived from the owner's postcode (preferring the postcode, falling back to the city
319	     * table, else {@code 'UNKNOWN'}; see {@link OwnerMapper#regionOf(Owner)}), FY is the two-digit fiscal
320	     * year (starting 1 July; see {@link OwnerMapper#fiscalYear(LocalDate)}) of the business-day-adjusted
321	     * registration date, HASH8 is the first 8 upper-case hex characters of the SHA-256 digest of the
322	     * owner's normalized E.164 telephone concatenated with the last name, and CHK is a single Luhn check
323	     * digit computed over the digits of {@code '<REGION><FY><HASH8>'} (see
324	     * {@link IdentityKeyUtils#luhnCheckDigit(String)}), e.g. {@code 'NSW271A2B3C4D5'}. The id carries no
325	     * sequence number, so its base form is a stable function of the owner's region, fiscal year and
326	     * telephone/last-name identity rather than of creation order.
327	     *
328	     * <p>When that computed id already belongs to an existing owner it is de-duplicated by appending
329	     * {@code '-<n>'} with the smallest {@code n} of 2 or more that yields an id no existing owner
330	     * already has; the de-duplicated id is returned.
331	     *
332	     * @param owner the owner being created, with its telephone already normalized to E.164 form and its
333	     *              registration date already business-day-adjusted
334	     * @return the assigned, collision-free member id
335	     */
336	    private String memberIdFor(Owner owner) {
337	        String region = ownerMapper.regionOf(owner);
338	        String fy = String.format("%02d", OwnerMapper.fiscalYear(owner.getRegistrationDate()) % 100);
339	        String hash8 = IdentityKeyUtils.sha256UpperHex(owner.getTelephone() + owner.getLastName())
340	            .substring(0, 8);
341	        String base = region + fy + hash8;
342	        String memberId = base + IdentityKeyUtils.luhnCheckDigit(base);
343	        if (!isMemberIdInUse(memberId)) {
344	            return memberId;
345	        }
346	        int n = 2;
347	        String candidate = memberId + "-" + n;
348	        while (isMemberIdInUse(candidate)) {
349	            n++;
350	            candidate = memberId + "-" + n;
351	        }
352	        return candidate;
353	    }
354	
355	    /**
356	     * Determines whether any existing owner already carries the given {@code memberId}, compared
357	     * exactly. Called while assigning a new owner's member id so collisions can be de-duplicated.
358	     *
359	     * @param memberId the candidate member id to look for
360	     * @return {@code true} if an existing owner already has that member id
361	     */
362	    private boolean isMemberIdInUse(String memberId) {
363	        for (Owner existing : this.clinicService.findAllOwners()) {
364	            if (memberId.equals(existing.getMemberId())) {
365	                return true;
366	            }
367	        }
368	        return false;
369	    }
370	
371	    /**
372	     * The maximum number of owners allowed to live in a single city. A create is rejected once the
373	     * owner's city already contains this many owners.
374	     */
375	    private static final int CITY_CAPACITY = 50;
376	
377	    /**
378	     * The number of owners a city must already contain before a new owner in it is flagged with
379	     * {@code capacityWarning}. Once the city holds this many owners (but fewer than
380	     * {@link #CITY_CAPACITY}), the create still succeeds but is flagged as approaching the capacity
381	     * limit.
382	     */
383	    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
384	
385	    /**
386	     * The maximum number of owners that may be created on a single day. A create is rejected with
387	     * {@link HttpStatus#TOO_MANY_REQUESTS} once this many owners already have today's
388	     * {@code registrationDate}.
389	     */
390	    private static final int DAILY_CREATE_LIMIT = 100;
391	
392	    /**
393	     * The number of owners that must already have been created for the current day before a new
394	     * create is flagged with {@code bulkSignupWarning}. The warning is set once more than this many
395	     * owners already carry today's {@code registrationDate}.
396	     */
397	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
398	
399	    /**
400	     * The fixed public holidays that the business-day roll skips. A registration date landing on one
401	     * of these dates is rolled forward, exactly as it is for a weekend day.
402	     */
403	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
404	        LocalDate.parse("2026-01-01"),
405	        LocalDate.parse("2026-01-26"),
406	        LocalDate.parse("2026-04-25"),
407	        LocalDate.parse("2026-12-25"),
408	        LocalDate.parse("2026-12-28"));
409	
410	    /**
411	     * Rolls a registration date forward onto a business day: a date that falls on a Saturday, a
412	     * Sunday or a listed public holiday is advanced one day at a time until it lands on a weekday
413	     * that is not a public holiday, while a date already on a non-holiday weekday is returned
414	     * unchanged. Applied to the effective registration date (supplied or defaulted to the server
415	     * date) so that the stored {@code registrationDate}, and every value derived from it, always
416	     * falls on a business day.
417	     *
418	     * @param date the effective registration date
419	     * @return the same date when it is a non-holiday weekday, otherwise the next such business day
420	     */
421	    private static LocalDate rollToBusinessDay(LocalDate date) {
422	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
423	            date = date.plusDays(1);
424	        }
425	        return date;
426	    }
427	
428	    private static boolean isWeekend(LocalDate date) {
429	        return switch (date.getDayOfWeek()) {
430	            case SATURDAY, SUNDAY -> true;
431	            default -> false;
432	        };
433	    }
434	
435	    /**
436	     * Counts the existing owners whose {@code registrationDate} equals the given (already
437	     * business-day-adjusted) date, i.e. the number of owners that have already been created for that
438	     * business day. Called before a new owner is saved, so the returned value reflects the number of
439	     * owners created for that day prior to this create.
440	     *
441	     * @param date the adjusted business-day registration date to count against
442	     * @return the number of existing owners registered on that date
443	     */
444	    private int countOwnersRegisteredOn(LocalDate date) {
445	        return (int) this.clinicService.findAllOwners().stream()
446	            .filter(existing -> date.equals(existing.getRegistrationDate()))
447	            .count();
448	    }
449	
450	    /**
451	     * Counts the existing owners that live in the given city, comparing city names case-insensitively.
452	     *
453	     * @param city the city to count owners for
454	     * @return the number of existing owners in that city
455	     */
456	    private int countOwnersInCity(String city) {
457	        return (int) this.clinicService.findAllOwners().stream()
458	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
459	            .count();
460	    }
461	
462	    /**
463	     * Counts the existing owners that already share the given first name and last name, comparing
464	     * both case-insensitively. Called before a new owner is saved, so the returned value reflects
465	     * the number of namesakes that existed prior to this create.
466	     *
467	     * @param firstName the new owner's first name
468	     * @param lastName  the new owner's last name
469	     * @return the number of existing owners with the same first and last name
470	     */
471	    private int countNamesakes(String firstName, String lastName) {
472	        int count = 0;
473	        for (Owner existing : this.clinicService.findAllOwners()) {
474	            if (firstName.equalsIgnoreCase(existing.getFirstName())
475	                && lastName.equalsIgnoreCase(existing.getLastName())) {
476	                count++;
477	            }
478	        }
479	        return count;
480	    }
481	
482	    /**
483	     * Counts the existing owners that already belong to the given household (i.e. that share the
484	     * given {@code householdId}). Called before a new owner is saved, so adding one for the owner
485	     * being created yields the household's total size at the moment of creation. Owners without a
486	     * household id are ignored.
487	     *
488	     * @param householdId the new owner's assigned household id
489	     * @return the number of existing owners already in that household
490	     */
491	    private int countHouseholdMembers(String householdId) {
492	        if (householdId == null) {
493	            return 0;
494	        }
495	        int count = 0;
496	        for (Owner existing : this.clinicService.findAllOwners()) {
497	            if (householdId.equals(existing.getHouseholdId())) {
498	                count++;
499	            }
500	        }
501	        return count;
502	    }
503	
504	    /**
505	     * Computes the membership-level ceiling for a new owner joining the given household: one above the
506	     * current maximum effective membership level among the existing owners in that household. The
507	     * ceiling is frozen on the owner at creation and later applied by
508	     * {@link OwnerMapper#toMembershipLevel(Owner)}. Returns {@code null} when the household has no
509	     * existing member (or the owner has no household id), meaning no cap applies.
510	     *
511	     * @param householdId the new owner's assigned household id
512	     * @return one above the household's current maximum membership level, or {@code null} when the
513	     *         household has no existing member
514	     */
515	    private Integer householdMembershipLevelCap(String householdId) {
516	        if (householdId == null) {
517	            return null;
518	        }
519	        Integer maxLevel = null;
520	        for (Owner existing : this.clinicService.findAllOwners()) {
521	            if (householdId.equals(existing.getHouseholdId())) {
522	                int level = ownerMapper.toMembershipLevel(existing);
523	                if (maxLevel == null || level > maxLevel) {
524	                    maxLevel = level;
525	                }
526	            }
527	        }
528	        return maxLevel == null ? null : maxLevel + 1;
529	    }
530	
531	    /**
532	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
533	     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
534	     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
535	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
536	     * string is what gets stored and returned.
537	     *
538	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
539	     *
540	     * <p>Once in E.164 form the national-number length is validated against the country code: a
541	     * {@code +61} (Australia) number must carry exactly 9 national digits and a {@code +1} (NANP)
542	     * number exactly 10 (see {@link E164PhoneNumbers#NATIONAL_LENGTHS}). Country codes without a configured
543	     * rule are accepted on the general 8-to-15 digit length alone.
544	     *
545	     * @param telephone the raw telephone value supplied by the client
546	     * @return the normalized E.164 telephone number
547	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
548	     *                                 valid E.164 number (unexpected characters, not 8 to 15 digits
549	     *                                 after the {@code '+'}, or the wrong national-number length for
550	     *                                 its country code)
551	     */
552	    private static String normalizeTelephone(String telephone) {
553	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
554	        String digits;
555	        if (cleaned.startsWith("+")) {
556	            digits = cleaned.substring(1);
557	        } else {
558	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
559	            digits = "61" + national;
560	        }
561	        if (!digits.matches("[0-9]{8,15}")) {
562	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
563	                "telephone could not be normalized to a valid E.164 number");
564	        }
565	        validateNationalNumberLength(digits);
566	        return "+" + digits;
567	    }
568	
569	    /**
570	     * Validates the national-number length of an E.164 number (its digits, without the leading
571	     * {@code '+'}) against its country code. The longest dialling code that prefixes the number (see
572	     * {@link E164PhoneNumbers#countryCode}) selects the rule; if none is configured the number passes
573	     * (only the general 8-to-15 digit rule applies).
574	     *
575	     * @param digits the E.164 digits without the leading {@code '+'}
576	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the number of national
577	     *                                 digits does not match the country code's required length
578	     */
579	    private static void validateNationalNumberLength(String digits) {
580	        E164PhoneNumbers.countryCode(digits)
581	            .ifPresent(code -> {
582	                int nationalLength = digits.length() - code.length();
583	                int required = E164PhoneNumbers.NATIONAL_LENGTHS.get(code);
584	                if (nationalLength != required) {
585	                    throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
586	                        "telephone must have " + required
587	                            + " national digits for country code +" + code);
588	                }
589	            });
590	    }
591	
592	    /**
593	     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
594	     * containing at least one dot, none of the three sections containing whitespace or an
595	     * additional {@code @}.
596	     */
597	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
598	
599	    /**
600	     * Disposable email domains that are not accepted for an owner. An email whose domain is on this
601	     * blocklist is rejected with {@link HttpStatus#BAD_REQUEST}. Entries are lower-case and matched
602	     * case-insensitively against the domain (the part after the {@code @}).
603	     */
604	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
605	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
606	
607	    /**
608	     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
609	     * (email is optional). When a value is supplied it must be a syntactically valid address whose
610	     * domain is not on the disposable-domain blocklist; the value is then stored and returned
611	     * lower-cased.
612	     *
613	     * @param email the raw email value supplied by the client, possibly {@code null}
614	     * @return the lower-cased email, or {@code null} when none was supplied
615	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
616	     *                                 is not a syntactically valid address, or its domain is on the
617	     *                                 disposable-domain blocklist
618	     */
619	    private static String normalizeEmail(String email) {
620	        if (email == null) {
621	            return null;
622	        }
623	        if (!EMAIL_PATTERN.matcher(email).matches()) {
624	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
625	                "email must be a syntactically valid address");
626	        }
627	        String normalized = email.toLowerCase(Locale.ROOT);
628	        String domain = normalized.substring(normalized.indexOf('@') + 1);
629	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
630	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
631	                "email domain " + domain + " is not allowed");
632	        }
633	        return normalized;
634	    }
635	
636	    /**
637	     * Fixed region-to-inclusive-postcode-range table. The postcode of an owner whose city maps to a
638	     * known region (via {@link OwnerMapper#CITY_REGION}) must fall within its region's range: NSW
639	     * 2000-2099, VIC 3000-3099, QLD 4000-4099. Each entry is {@code {low, high}} inclusive.
640	     */
641	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
642	        "NSW", new int[] {2000, 2099},
643	        "VIC", new int[] {3000, 3099},
644	        "QLD", new int[] {4000, 4099});
645	
646	    /**
647	     * Validates an owner's optional postcode against the city's region. Postcode is validated only
648	     * when present ({@code null} is accepted, keeping the request contract backward-compatible). The
649	     * four-digit format is enforced by request validation; here the value is range-checked: when the
650	     * city maps to a known region (via {@link OwnerMapper#CITY_REGION}) the postcode must fall within
651	     * that region's inclusive range (see {@link #REGION_POSTCODE_RANGES}). A city with no known region
652	     * accepts any four-digit postcode.
653	     *
654	     * @param city     the owner's city
655	     * @param postcode the owner's postcode, possibly {@code null}
656	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a supplied postcode is
657	     *                                 out of range for the city's region
658	     */
659	    private static void validatePostcode(String city, String postcode) {
660	        if (postcode == null) {
661	            return;
662	        }
663	        String region = OwnerMapper.CITY_REGION.get(city);
664	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
665	        if (range == null) {
666	            return;
667	        }
668	        int value = Integer.parseInt(postcode);
669	        if (value < range[0] || value > range[1]) {
670	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
671	                "postcode " + postcode + " is not valid for region " + region);
672	        }
673	    }
674	
675	    /**
676	     * Common street-type abbreviations expanded to their full word during address normalization.
677	     * Keys and values are upper-case; matching is done per whitespace-delimited token.
678	     */
679	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
680	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
681	
682	    /**
683	     * Applies an owner's address, accepting either the structured form (a non-blank
684	     * {@code addressLine1} with an optional {@code addressLine2}) or the flat {@code address} form,
685	     * preferring the structured fields when present. Whichever fields are supplied are normalized
686	     * (see {@link #normalizeAddress(String)}), and the stored flat {@code address} is set to the
687	     * composed value: the normalized {@code addressLine1}, with a single space and the normalized
688	     * {@code addressLine2} appended when an {@code addressLine2} was supplied. When only the flat
689	     * form is supplied, the normalized flat address is stored and both structured lines are cleared.
690	     * This keeps the request contract backward-compatible: an owner that supplied just the flat
691	     * {@code address} (plus city) is still accepted.
692	     *
693	     * @param owner the owner being created or updated, carrying the raw address fields
694	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if neither a non-blank
695	     *                                 {@code addressLine1} nor a non-blank flat {@code address} was
696	     *                                 supplied
697	     */
698	    private static void applyAddress(Owner owner) {
699	        boolean hasStructured = owner.getAddressLine1() != null && !owner.getAddressLine1().isBlank();
700	        boolean hasFlat = owner.getAddress() != null && !owner.getAddress().isBlank();
701	        if (!hasStructured && !hasFlat) {
702	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
703	                "an address must be supplied, either 'addressLine1' or 'address'");
704	        }
705	        if (hasStructured) {
706	            String line1 = normalizeAddress(owner.getAddressLine1());
707	            owner.setAddressLine1(line1);
708	            String composed = line1;
709	            if (owner.getAddressLine2() != null && !owner.getAddressLine2().isBlank()) {
710	                String line2 = normalizeAddress(owner.getAddressLine2());
711	                owner.setAddressLine2(line2);
712	                composed = line1 + " " + line2;
713	            } else {
714	                owner.setAddressLine2(null);
715	            }
716	            owner.setAddress(composed);
717	        } else {
718	            owner.setAddressLine1(null);
719	            owner.setAddressLine2(null);
720	            owner.setAddress(normalizeAddress(owner.getAddress()));
721	        }
722	    }
723	
724	    /**
725	     * Normalizes an owner address for storage. Leading/trailing whitespace is trimmed and internal
726	     * runs of whitespace are collapsed to a single space, the value is upper-cased, and common
727	     * street-type abbreviations are expanded per token ({@code ST -> STREET}, {@code RD -> ROAD},
728	     * {@code AVE -> AVENUE}). This normalized value is what gets stored and returned.
729	     *
730	     * <p>For example {@code "  12  main  st "} is normalized to {@code "12 MAIN STREET"}.
731	     *
732	     * @param address the raw address supplied by the client, possibly {@code null}
733	     * @return the normalized address
734	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the address is blank
735	     *                                 after normalization (required field)
736	     */
737	    private static String normalizeAddress(String address) {
738	        String collapsed = address == null ? "" : address.trim().replaceAll("\\s+", " ");
739	        if (collapsed.isEmpty()) {
740	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
741	                "address must not be blank");
742	        }
743	        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
744	        StringBuilder normalized = new StringBuilder();
745	        for (int i = 0; i < tokens.length; i++) {
746	            if (i > 0) {
747	                normalized.append(' ');
748	            }
749	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
750	        }
751	        return normalized.toString();
752	    }
753	
754	    /**
755	     * Determines whether the given whole identity key already belongs to any owner other than the
756	     * one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g. on
757	     * create). The key is derived in one place — {@link OwnerMapper#toIdentityKey(Owner)}, the same
758	     * method that builds the {@code identityKey} returned on the DTO — so the value governing the
759	     * 409 is exactly the value clients see. Only an exact full-key match counts as a duplicate.
760	     *
761	     * @param identityKey the identity key to look for
762	     * @param excludeId   id of an owner to ignore during the check, or {@code null} for none
763	     * @return {@code true} if another owner already has the same identity key
764	     */
765	    private boolean isIdentityKeyInUse(String identityKey, Integer excludeId) {
766	        for (Owner existing : this.clinicService.findAllOwners()) {
767	            if (existing.isDeleted()) {
768	                continue;
769	            }
770	            if (excludeId != null && excludeId.equals(existing.getId())) {
771	                continue;
772	            }
773	            if (identityKey.equals(ownerMapper.toIdentityKey(existing))) {
774	                return true;
775	            }
776	        }
777	        return false;
778	    }
779	
780	    /**
781	     * Finds the existing owner that the given (not-a-hard-duplicate) new owner is a possible
782	     * (soft) duplicate of: one whose identity key <em>differs</em> from the new owner's while sharing
783	     * the same last-name Soundex code (see {@link IdentityKeyUtils#soundex(String)}) and postcode. A
784	     * hard duplicate (identical identity key) has already been rejected with a 409 before this runs, so
785	     * this flags only the softer same-household-name overlap — in particular two owners with the same
786	     * last name and postcode but different telephones (whose identity keys therefore differ) are a soft
787	     * match rather than a rejected duplicate. The match with the lowest id is returned so the result is
788	     * deterministic when several owners qualify.
789	     *
790	     * @param owner the new owner being created, with its telephone already normalized
791	     * @return the matching existing owner, or {@code null} when none qualifies
792	     */
793	    private Owner findPossibleDuplicate(Owner owner) {
794	        if (owner.getLastName() == null || owner.getPostcode() == null) {
795	            return null;
796	        }
797	        String identityKey = ownerMapper.toIdentityKey(owner);
798	        String soundex = IdentityKeyUtils.soundex(owner.getLastName());
799	        return this.clinicService.findAllOwners().stream()
800	            .filter(existing -> !existing.isDeleted())
801	            .filter(existing -> !identityKey.equals(ownerMapper.toIdentityKey(existing)))
802	            .filter(existing -> soundex.equals(IdentityKeyUtils.soundex(existing.getLastName())))
803	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
804	            .min(Comparator.comparingInt(Owner::getId))
805	            .orElse(null);
806	    }
807	
808	}
